208	
209	// FakeHTTP plays the organizations' webhook receivers: it records every request and answers 200, or what Respond returns
210	// when it is set (a status code, or an error for a request that never got an answer).
211	type FakeHTTP struct {
212		// Respond, when set, answers each request. Set it before requests are made, or between them.
213		Respond func(r Request) (int, error)
214	
215		mu       sync.Mutex
216		requests []Request
217	}
218	
219	// Request is a request a FakeHTTP received.
220	type Request struct {
221		Method string
222		URL    string
223		Header http.Header
224		Body   []byte
225	}
226	
227	// Do implements webhooks.Doer.
228	func (f *FakeHTTP) Do(req *http.Request) (*http.Response, error) {
229		var body []byte
230		if req.Body != nil {
231			body, _ = io.ReadAll(req.Body)
232			req.Body.Close()
233		}
234		r := Request{Method: req.Method, URL: req.URL.String(), Header: req.Header.Clone(), Body: body}
235		f.mu.Lock()
236		f.requests = append(f.requests, r)
237		respond := f.Respond
238		f.mu.Unlock()
239		status := http.StatusOK
240		if respond != nil {
241			var err error
242			if status, err = respond(r); err != nil {
243				return nil, err
244			}
245		}
246		return &http.Response{StatusCode: status, Status: http.StatusText(status), Header: http.Header{}, Body: io.NopCloser(strings.NewReader("")), Request: req}, nil
247	}
248	
249	// Requests returns the requests received so far, oldest first.
250	func (f *FakeHTTP) Requests() []Request {
251		f.mu.Lock()
252		defer f.mu.Unlock()
253		return append([]Request(nil), f.requests...)
254	}
255	
256	// FakeDNS answers host lookups from the addresses Set gave it. Other hosts do not resolve.
257	type FakeDNS struct {
258		mu    sync.Mutex
259		hosts map[string][]string
260	}
261	
262	// Set makes host resolve to ips (none: the host does not resolve).
263	func (d *FakeDNS) Set(host string, ips ...string) {
264		d.mu.Lock()
265		defer d.mu.Unlock()
266		if d.hosts == nil {
267			d.hosts = map[string][]string{}
268		}
269		d.hosts[strings.ToLower(host)] = ips
270	}
271	
272	// LookupIPAddr implements webhooks.Resolver.
273	func (d *FakeDNS) LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error) {
274		d.mu.Lock()
275		ips := d.hosts[strings.ToLower(host)]
276		d.mu.Unlock()
277		if len(ips) == 0 {
278			return nil, &net.DNSError{Err: "no such host", Name: host, IsNotFound: true}
279		}
280		out := make([]net.IPAddr, 0, len(ips))
281		for _, s := range ips {
282			ip := net.ParseIP(s)
283			if ip == nil {
284				return nil, fmt.Errorf("FakeDNS: %q is not an IP address", s)
285			}
286			out = append(out, net.IPAddr{IP: ip})
287		}
288		return out, nil
289	}
