// Package webhooks sends an organization's events to its webhook endpoints.
package webhooks

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"slices"
	"sync"
	"time"

	"example.com/tally/internal/clock"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/store"
)

// Doer sends HTTP requests (an *http.Client).
type Doer interface {
	Do(*http.Request) (*http.Response, error)
}

// Resolver looks up host names (a *net.Resolver).
type Resolver interface {
	LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error)
}

// Options configure a Service.
type Options struct {
	Store *store.Store
	Clock clock.Clock
	// Doer sends the deliveries; nil means an HTTP client with a 10 second timeout that does not follow redirects.
	Doer Doer
	// Resolver checks endpoint hosts; nil means net.DefaultResolver.
	Resolver Resolver
	// Mail sends the owners the emails about endpoints that keep failing; nil means an Outbox (nothing is sent).
	Mail mail.Sender
}

// Service manages endpoints' URLs and sends deliveries.
type Service struct {
	store    *store.Store
	clock    clock.Clock
	doer     Doer
	resolver Resolver
	mail     mail.Sender

	mu       sync.Mutex
	lastMail map[string]time.Time // when each endpoint's owners were last emailed about failures
}

// New returns a Service.
func New(opt Options) *Service {
	s := &Service{store: opt.Store, clock: opt.Clock, doer: opt.Doer, resolver: opt.Resolver, mail: opt.Mail, lastMail: map[string]time.Time{}}
	if s.clock == nil {
		s.clock = clock.Real{}
	}
	if s.doer == nil {
		s.doer = &http.Client{Timeout: 10 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	}
	if s.resolver == nil {
		s.resolver = net.DefaultResolver
	}
	if s.mail == nil {
		s.mail = &mail.Outbox{}
	}
	return s
}

// retryDelays are the waits after each failed attempt: after the first failure the delivery is tried again after the first
// delay, after the second failure after the second, and so on.
var retryDelays = []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}

// maxAttempts is how many attempts a delivery gets before it fails for good.
var maxAttempts = len(retryDelays) + 1

// EventTypes are the events Tally sends. An endpoint subscribes to some of them, or to "*" for all.
var EventTypes = []string{
	"customer.created", "customer.updated", "customer.deleted",
	"subscription.created", "subscription.updated", "subscription.canceled",
	"invoice.created", "invoice.paid", "invoice.payment_failed", "invoice.voided",
}

// Errors.
var (
	ErrInvalidURL    = errors.New("invalid webhook URL")
	ErrInvalidEvents = errors.New("invalid event types")
)

// CheckURL checks a webhook URL before it is saved: an absolute http or https URL whose host resolves.
func (s *Service) CheckURL(ctx context.Context, raw string) error {
	u, err := url.Parse(raw)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
		return fmt.Errorf("%w: use an absolute http or https URL", ErrInvalidURL)
	}
	host := u.Hostname()
	if net.ParseIP(host) != nil {
		return nil
	}
	addrs, err := s.resolver.LookupIPAddr(ctx, host)
	if err != nil || len(addrs) == 0 {
		return fmt.Errorf("%w: the host %q does not resolve", ErrInvalidURL, host)
	}
	return nil
}

// CheckEvents checks an endpoint's event types.
func CheckEvents(types []string) error {
	if len(types) == 0 {
		return fmt.Errorf("%w: name at least one event type, or \"*\"", ErrInvalidEvents)
	}
	for _, t := range types {
		if t != "*" && !slices.Contains(EventTypes, t) {
			return fmt.Errorf("%w: unknown event type %q", ErrInvalidEvents, t)
		}
	}
	return nil
}

// NewSecret returns a new signing secret for an endpoint.
func NewSecret() string { return store.NewToken("whsec_") }

// Sign returns the signature of a delivery's body: the hex HMAC-SHA256 of the body, keyed with the endpoint's secret.
func Sign(secret string, body []byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	m.Write(body)
	return hex.EncodeToString(m.Sum(nil))
}

// Publish records an event and queues a delivery of it to every enabled endpoint of the organization that subscribes to its
// type. The deliveries are sent by RunDue.
func (s *Service) Publish(ctx context.Context, orgID, eventType string, data any) error {
	raw, err := json.Marshal(data)
	if err != nil {
		return err
	}
	now := s.clock.Now()
	e, err := s.store.AddEvent(orgID, eventType, raw, now)
	if err != nil {
		return err
	}
	for _, ep := range s.store.WebhookEndpoints(orgID) {
		if !ep.Enabled || !(slices.Contains(ep.Events, "*") || slices.Contains(ep.Events, eventType)) {
			continue
		}
		next := now
		if _, err := s.store.CreateDelivery(store.Delivery{OrgID: orgID, EndpointID: ep.ID, EventID: e.ID, NextAttemptAt: &next}, now); err != nil {
			return err
		}
	}
	return nil
}

// RunDue attempts every delivery that is due and returns how many attempts it made. An attempt whose answer is 2xx succeeds.
// Any other attempt fails: the delivery is tried again after the next retry delay, and fails for good after its last attempt
// or at once when the endpoint answers 410 Gone.
func (s *Service) RunDue(ctx context.Context) (int, error) {
	n := 0
	var mailErr error
	for _, d := range s.store.DueDeliveries(s.clock.Now()) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		attempted, err := s.deliver(ctx, d)
		if attempted {
			n++
		}
		mailErr = errors.Join(mailErr, err)
	}
	return n, mailErr
}

// Body is what a delivery POSTs.
type Body struct {
	ID        string          `json:"id"`
	Type      string          `json:"type"`
	CreatedAt time.Time       `json:"created_at"`
	Data      json.RawMessage `json:"data"`
}

// deliver makes one attempt at a due delivery and reports whether it made one. A delivery that can no longer be sent (its
// endpoint is disabled or deleted, or its event is gone) fails for good without an attempt.
func (s *Service) deliver(ctx context.Context, due store.Delivery) (bool, error) {
	d, ok := s.store.Delivery(due.ID)
	if !ok || d.Status != store.DeliveryPending {
		// An earlier delivery in this run may have failed it already.
		return false, nil
	}
	ep, epOK := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eOK := s.store.EventByID(d.EventID)
	if !epOK || !ep.Enabled || !eOK {
		reason := "the endpoint is disabled or was deleted"
		if !eOK {
			reason = "the event no longer exists"
		}
		s.failForGood(d.ID, reason)
		return false, nil
	}
	status, errText := s.send(ctx, ep, e)
	now := s.clock.Now()
	var exhausted bool
	_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts++
		d.LastAttemptAt = &now
		d.NextAttemptAt = nil
		d.ResponseStatus = status
		d.Error = errText
		switch {
		case errText == "":
			d.Status = store.DeliverySucceeded
		case status == http.StatusGone || d.Attempts >= maxAttempts:
			d.Status = store.DeliveryFailed
			exhausted = status != http.StatusGone
		default:
			d.Status = store.DeliveryPending
			next := now.Add(retryDelays[d.Attempts-1])
			d.NextAttemptAt = &next
		}
		return nil
	})
	if errText == "" {
		return true, nil
	}
	if status == http.StatusGone {
		// The endpoint is gone: stop sending to it, and fail its other pending deliveries without sending them.
		_, _ = s.store.UpdateWebhookEndpoint(ep.OrgID, ep.ID, func(ep *store.WebhookEndpoint) error {
			ep.Enabled = false
			ep.DisabledReason = "gone"
			return nil
		})
		s.failPending(ep.OrgID, ep.ID)
		return true, nil
	}
	if exhausted {
		return true, s.notifyOwners(ctx, ep, errText)
	}
	return true, nil
}

// failForGood marks a delivery failed without sending it again.
func (s *Service) failForGood(id, reason string) {
	_, _ = s.store.UpdateDelivery(id, func(d *store.Delivery) error {
		d.Status = store.DeliveryFailed
		d.NextAttemptAt = nil
		d.Error = reason
		return nil
	})
}

// failPending fails every pending delivery of an endpoint.
func (s *Service) failPending(orgID, endpointID string) {
	for _, d := range s.store.Deliveries(orgID, endpointID) {
		if d.Status == store.DeliveryPending {
			s.failForGood(d.ID, "the endpoint is disabled or was deleted")
		}
	}
}

// notifyOwners emails every owner of the endpoint's organization that the endpoint keeps failing. It emails at most once per
// endpoint in 24 hours.
func (s *Service) notifyOwners(ctx context.Context, ep store.WebhookEndpoint, lastErr string) error {
	now := s.clock.Now()
	s.mu.Lock()
	defer s.mu.Unlock()
	if last, ok := s.lastMail[ep.ID]; ok && now.Sub(last) < 24*time.Hour {
		return nil
	}
	s.lastMail[ep.ID] = now
	var errs error
	for _, m := range s.store.Members(ep.OrgID) {
		if m.Role != store.RoleOwner {
			continue
		}
		u, ok := s.store.User(m.UserID)
		if !ok {
			continue
		}
		errs = errors.Join(errs, s.mail.Send(ctx, mail.Message{
			To:      u.Email,
			Subject: "Webhook endpoint failing: " + ep.URL,
			Body: fmt.Sprintf("Tally could not deliver webhook events to %s after %d attempts, and has stopped trying the failed delivery.\n\n"+
