func TestSlowAnswerIsAFailure(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	// The attempt's request must carry a deadline 10 seconds away; the Doer then fails the way a request does past it.
	doer := deadlineDoer{t: t}
	s := webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock, Doer: doer, Resolver: e.DNS, Mail: e.Mail})
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/slow", Events: []string{"*"}, Secret: "whsec_s", Enabled: true}, e.Clock.Now())
