	now := e.Clock.Now()
	all, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, now)
	paid, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/paid", Events: []string{"invoice.paid"}, Secret: "whsec_b", Enabled: true}, now)
	_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/off", Events: []string{"*"}, Secret: "whsec_c", Enabled: false}, now)
	_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Globex.ID, URL: "https://hooks.globex.example/", Events: []string{"*"}, Secret: "whsec_d", Enabled: true}, now)

	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	n, err := e.Webhooks.RunDue(ctx)
	if err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v (only the endpoint for every event wants customer.created)", n, err)
	}
	reqs := e.HTTP.Requests()
	if len(reqs) != 1 || reqs[0].URL != all.URL || reqs[0].Method != http.MethodPost {
		t.Fatalf("requests = %+v", reqs)
	}
	if got, want := reqs[0].Header.Get("Tally-Signature"), webhooks.Sign("whsec_a", reqs[0].Body); got != want {
		t.Fatalf("signature %q, want %q", got, want)
	}
	var body webhooks.Body
	if err := json.Unmarshal(reqs[0].Body, &body); err != nil || body.Type != "customer.created" || reqs[0].Header.Get("Tally-Event-Id") != body.ID {
		t.Fatalf("body = %s (%v)", reqs[0].Body, err)
	}
	ds := e.Store.Deliveries(e.Acme.ID, all.ID)
	if len(ds) != 1 || ds[0].Status != store.DeliverySucceeded || ds[0].Attempts != 1 || ds[0].ResponseStatus != 200 {
		t.Fatalf("deliveries = %+v", ds)
	}

	e.HTTP.Respond = func(r apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_1"})
	if n, _ := e.Webhooks.RunDue(ctx); n != 2 {
		t.Fatalf("RunDue = %d, want 2", n)
	}
	for _, ep := range []store.WebhookEndpoint{all, paid} {
		ds := e.Store.Deliveries(e.Acme.ID, ep.ID)
		last := ds[len(ds)-1]
		if last.Status != store.DeliveryPending || last.Attempts != 1 || last.ResponseStatus != 500 || last.Error == "" ||
			last.NextAttemptAt == nil || !last.NextAttemptAt.Equal(e.Clock.Now().Add(time.Minute)) {
			t.Fatalf("delivery to %s = %+v", ep.URL, last)
		}
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a failed delivery was sent again before its retry: %d", n)
	}
}

// onlyDelivery returns the single delivery of an endpoint.
func onlyDelivery(t *testing.T, e *apitest.Env, endpointID string) store.Delivery {
	t.Helper()
	ds := e.Store.Deliveries(e.Acme.ID, endpointID)
	if len(ds) != 1 {
		t.Fatalf("deliveries = %+v, want one", ds)
	}
	return ds[0]
}

// runAllAttempts runs the due deliveries at each retry time: now, then after each wait, until the last attempt.
func runAllAttempts(t *testing.T, e *apitest.Env) {
	t.Helper()
	for i := 0; i <= len(retryWaits); i++ {
		if i > 0 {
			e.Clock.Advance(retryWaits[i-1])
		}
		if _, err := e.Webhooks.RunDue(context.Background()); err != nil {
			t.Fatal(err)
		}
	}
}

func TestRetrySchedule(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/retry", Events: []string{"*"}, Secret: "whsec_r", Enabled: true}, e.Clock.Now())
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusServiceUnavailable, nil }
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	for attempt := 1; attempt <= 7; attempt++ {
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("attempt %d: RunDue = %d, %v", attempt, n, err)
		}
		d := onlyDelivery(t, e, ep.ID)
		if d.Attempts != attempt || d.ResponseStatus != http.StatusServiceUnavailable || d.Error == "" || d.LastAttemptAt == nil || !d.LastAttemptAt.Equal(e.Clock.Now()) {
			t.Fatalf("after attempt %d: %+v", attempt, d)
		}
		if attempt == 7 {
			if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
				t.Fatalf("after the last attempt: %+v", d)
			}
			break
		}
		wait := retryWaits[attempt-1]
		if d.Status != store.DeliveryPending || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(e.Clock.Now().Add(wait)) {
			t.Fatalf("after attempt %d: want the next attempt %v later: %+v", attempt, wait, d)
		}
		e.Clock.Advance(wait - time.Second)
		if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
			t.Fatalf("attempt %d was due a second early", attempt+1)
		}
		e.Clock.Advance(time.Second)
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a failed delivery was sent again: %d", n)
	}
	if got := len(e.HTTP.Requests()); got != 7 {
		t.Fatalf("requests = %d, want 7", got)
	}
	if b, _ := json.Marshal(store.Delivery{}); !strings.Contains(string(b), `"next_attempt_at":null`) {
		t.Fatalf("a delivery with no attempt planned should show next_attempt_at as null: %s", b)
	}
}

