// onlyDelivery returns the single delivery of an endpoint.
func onlyDelivery(t *testing.T, e *apitest.Env, endpointID string) store.Delivery {
	t.Helper()
	ds := e.Store.Deliveries(e.Acme.ID, endpointID)
	if len(ds) != 1 {
		t.Fatalf("deliveries = %+v, want one", ds)
	}
	return ds[0]
}

// runAllAttempts runs the due deliveries at each retry time: now, then after each wait, until the last attempt.
func runAllAttempts(t *testing.T, e *apitest.Env) {
	t.Helper()
	for i := 0; i <= len(retryWaits); i++ {
		if i > 0 {
			e.Clock.Advance(retryWaits[i-1])
		}
		if _, err := e.Webhooks.RunDue(context.Background()); err != nil {
			t.Fatal(err)
		}
	}
}

func TestRetrySchedule(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/retry", Events: []string{"*"}, Secret: "whsec_r", Enabled: true}, e.Clock.Now())
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusServiceUnavailable, nil }
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	for attempt := 1; attempt <= 7; attempt++ {
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("attempt %d: RunDue = %d, %v", attempt, n, err)
		}
		d := onlyDelivery(t, e, ep.ID)
		if d.Attempts != attempt || d.ResponseStatus != http.StatusServiceUnavailable || d.Error == "" || d.LastAttemptAt == nil || !d.LastAttemptAt.Equal(e.Clock.Now()) {
			t.Fatalf("after attempt %d: %+v", attempt, d)
		}
		if attempt == 7 {
			if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
				t.Fatalf("after the last attempt: %+v", d)
			}
			break
		}
		wait := retryWaits[attempt-1]
		if d.Status != store.DeliveryPending || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(e.Clock.Now().Add(wait)) {
			t.Fatalf("after attempt %d: want the next attempt %v later: %+v", attempt, wait, d)
		}
		e.Clock.Advance(wait - time.Second)
		if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
			t.Fatalf("attempt %d was due a second early", attempt+1)
		}
		e.Clock.Advance(time.Second)
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a failed delivery was sent again: %d", n)
	}
	if got := len(e.HTTP.Requests()); got != 7 {
		t.Fatalf("requests = %d, want 7", got)
	}
	if b, _ := json.Marshal(store.Delivery{}); !strings.Contains(string(b), `"next_attempt_at":null`) {
		t.Fatalf("a delivery with no attempt planned should show next_attempt_at as null: %s", b)
	}
}

func TestFailedAnswersAndNoAnswer(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/kinds", Events: []string{"*"}, Secret: "whsec_k", Enabled: true}, e.Clock.Now())
	cases := []struct {
		name    string
		respond func(apitest.Request) (int, error)
		status  store.DeliveryStatus
		code    int
	}{
		{"redirect is not followed", func(apitest.Request) (int, error) { return http.StatusFound, nil }, store.DeliveryPending, http.StatusFound},
		{"no answer", func(apitest.Request) (int, error) { return 0, errors.New("connection refused") }, store.DeliveryPending, 0},
		{"2xx succeeds", func(apitest.Request) (int, error) { return http.StatusNoContent, nil }, store.DeliverySucceeded, http.StatusNoContent},
	}
	for _, c := range cases {
		e.HTTP.Respond = c.respond
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"name": c.name}); err != nil {
			t.Fatal(err)
		}
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("%s: RunDue = %d, %v", c.name, n, err)
