		d := ds[len(ds)-1]
		if d.Status != c.status || d.ResponseStatus != c.code || (c.status == store.DeliveryPending) != (d.Error != "") {
			t.Fatalf("%s: delivery = %+v", c.name, d)
		}
	}
}

func TestSlowAnswerIsAFailure(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	// The attempt's request must carry a deadline 10 seconds away; the Doer then fails the way a request does past it.
	doer := deadlineDoer{t: t}
	s := webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock, Doer: doer, Resolver: e.DNS, Mail: e.Mail})
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/slow", Events: []string{"*"}, Secret: "whsec_s", Enabled: true}, e.Clock.Now())
	if err := s.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	if n, err := s.RunDue(ctx); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v", n, err)
	}
	d := onlyDelivery(t, e, ep.ID)
	if d.Status != store.DeliveryPending || d.Attempts != 1 || d.Error == "" || d.NextAttemptAt == nil {
		t.Fatalf("slow delivery = %+v", d)
	}
	if !doer.sawDeadline {
		t.Fatal("the request had no 10 second deadline")
	}
}

// deadlineDoer checks the deadline of each request and fails it.
type deadlineDoer struct {
	t           *testing.T
	sawDeadline bool
}

func (d deadlineDoer) Do(req *http.Request) (*http.Response, error) {
	dl, ok := req.Context().Deadline()
	if ok && time.Until(dl) > 9*time.Second && time.Until(dl) <= 10*time.Second {
		d.sawDeadline = true
	}
	return nil, context.DeadlineExceeded
}

func TestGoneDisablesEndpoint(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	now := e.Clock.Now()
	gone, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/gone", Events: []string{"*"}, Secret: "whsec_g", Enabled: true}, now)
	other, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/other", Events: []string{"*"}, Secret: "whsec_o", Enabled: true}, now)
	e.HTTP.Respond = func(r apitest.Request) (int, error) {
		if r.URL == gone.URL {
			return http.StatusGone, nil
		}
		return http.StatusOK, nil
	}
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"})
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "customer.updated", map[string]string{"id": "cus_1"})
	if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 3 {
		t.Fatalf("RunDue = %d, %v; want 3 (the gone endpoint's second delivery is not sent)", n, err)
	}

	ep, _ := e.Store.WebhookEndpoint(e.Acme.ID, gone.ID)
	if ep.Enabled || ep.DisabledReason != "gone" {
		t.Fatalf("endpoint = %+v, want disabled for gone", ep)
	}
	ds := e.Store.Deliveries(e.Acme.ID, gone.ID)
	if len(ds) != 2 || ds[0].Status != store.DeliveryFailed || ds[0].ResponseStatus != http.StatusGone || ds[0].Attempts != 1 ||
		ds[1].Status != store.DeliveryFailed || ds[1].Attempts != 0 || ds[1].NextAttemptAt != nil {
		t.Fatalf("gone deliveries = %+v", ds)
	}
	for _, d := range e.Store.Deliveries(e.Acme.ID, other.ID) {
		if d.Status != store.DeliverySucceeded {
			t.Fatalf("other endpoint's delivery = %+v", d)
		}
	}
	if n := len(e.HTTP.Requests()); n != 3 {
		t.Fatalf("requests = %d, want 3", n)
	}
	e.Clock.Advance(24 * time.Hour)
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a gone endpoint got %d more deliveries", n)
	}
	if msgs := e.Mail.Messages(); len(msgs) != 0 {
		t.Fatalf("a 410 emailed the owners: %+v", msgs)
	}
}

