// runAllAttempts runs the due deliveries at each retry time: now, then after each wait, until the last attempt.
func runAllAttempts(t *testing.T, e *apitest.Env) {
	t.Helper()
	for i := 0; i <= len(retryWaits); i++ {
		if i > 0 {
			e.Clock.Advance(retryWaits[i-1])
		}
		if _, err := e.Webhooks.RunDue(context.Background()); err != nil {
			t.Fatal(err)
		}
	}
}

args.new_string:
// runUntilSettled runs the endpoint's deliveries each time one falls due, until none is pending.
func runUntilSettled(t *testing.T, e *apitest.Env, endpointID string) {
	t.Helper()
	for {
		if _, err := e.Webhooks.RunDue(context.Background()); err != nil {
			t.Fatal(err)
		}
		var next *time.Time
		for _, d := range e.Store.Deliveries(e.Acme.ID, endpointID) {
			if d.Status == store.DeliveryPending && d.NextAttemptAt != nil && (next == nil || d.NextAttemptAt.Before(*next)) {
				next = d.NextAttemptAt
			}
		}
		if next == nil {
			return
		}
		e.Clock.Set(*next)
	}
}

